const prevData = $node["Load IndiaMART Module URLs"].json;
const response = $json;

const statusCode = response.statusCode || response.status || (response.error ? 500 : 200);
const bodyText = typeof response.body === 'string' ? response.body : JSON.stringify(response.body || '');

// Calculate real response time latency
const responseTimeMs = prevData.startTime ? (Date.now() - prevData.startTime) : 150;

// Determine Operational Time Window Tag
const hour = new Date().getHours();
let timeWindow = "Manual / Custom Run";
if (hour >= 4 && hour <= 6) {
  timeWindow = "Morning Shift (4 AM - 6 AM)";
} else if (hour >= 13 && hour <= 15) {
  timeWindow = "Afternoon Shift (1 PM - 3 PM)";
} else if (hour >= 18 && hour <= 21) {
  timeWindow = "Evening Shift (6 PM - 9 PM)";
} else if (hour === 23 || hour === 0) {
  timeWindow = "Night Shift (11 PM - 12 AM)";
}

const soft404Keywords = [
  "page not found",
  "product not found",
  "item unavailable",
  "404 not found",
  "something went wrong",
  "server error",
  "500 internal server error",
  "page missing",
  "no longer available",
  "under maintenance",
  "window.is404 = true",
  "pdp404: true"
];

const lowerBody = bodyText.toLowerCase();
let isSoft404 = false;
let detectedKeyword = "";

for (const kw of soft404Keywords) {
  if (lowerBody.includes(kw)) {
    isSoft404 = true;
    detectedKeyword = kw;
    break;
  }
}

let isHealthy = true;
let failureReason = "";

if (statusCode !== 200) {
  isHealthy = false;
  failureReason = `HTTP ${statusCode} Status Code`;
} else if (isSoft404) {
  isHealthy = false;
  failureReason = `Soft 404 Error: Detected phrase "${detectedKeyword}" in HTML content`;
} else if (bodyText.trim().length < 100) {
  isHealthy = false;
  failureReason = "Empty / Blank HTML Response Body";
}

const timestamp = new Date().toISOString();
const bugTitle = `[AUTOMATED ${isSoft404 ? 'SOFT 404' : 'PAGE DOWN'}] ${prevData.module_name} failing: ${failureReason}`;
const bugNotes = `AUTOMATED QA ALERT: ${prevData.module_name} (${prevData.page_type}) page health audit failed during ${timeWindow}.\n\nURL: ${prevData.url}\nStatus Code: ${statusCode}\nFailure Diagnostic: ${failureReason}\nOpenProject Bucket: ${prevData.project_name}\nAssigned QA: ${prevData.assigned_qa}\nReal Response Time: ${responseTimeMs}ms\nTime Window: ${timeWindow}\nTimestamp: ${timestamp}`;

const auth = prevData.apikey ? Buffer.from(`apikey:${prevData.apikey}`).toString("base64") : "";

return [{
  json: {
    ...prevData,
    statusCode: statusCode,
    isHealthy: isHealthy,
    isSoft404: isSoft404,
    failureReason: failureReason,
    responseTimeMs: responseTimeMs,
    timeWindow: timeWindow,
    timestamp: timestamp,
    bugTitle: bugTitle,
    bugNotes: bugNotes,
    authorization: auth ? `Basic ${auth}` : ""
  }
}];
